#nullable enable // autogenerated

using MVZ2Logic.Models;
using PVZEngine;
using UnityEngine;

namespace MVZ2.Models
{
    public class ModelFactory : IModelFactory
    {
        public ModelFactory()
        {
        }
        public IModelBuilder? GetModelBuilder(NamespaceID? id, Camera camera, int seed = 0)
